 s=re.sub(r'<a href="/offline/">Offline library</a>','<a href="/toolkits/">Preparation toolkits</a>',s)
 if '<footer' in s and 'href="/toolkits/">Preparation toolkits' not in s:s=s.replace('<a href="/privacy/">Privacy</a>','<a href="/toolkits/">Preparation toolkits</a><a href="/privacy/">Privacy</a>')
 s=s.replace('Preparation toolkits are in development.', 'Four topic toolkit editions are complete, with checkout opening soon.')
 s=s.replace('keep the essentials offline.','prepare before you need it.')
 s=s.replace('Save the checklist, follow practical steps and read the limits.','Follow practical steps and read the limits.')
 s=s.replace('Sources, review date &amp; printable checklist','Sources, scope &amp; review date').replace('Sources, review date & printable checklist','Sources, scope & review date')
 s=re.sub(r'<script src="/ads\.js[^"]*"[^>]*></script>\s*', '', s)
 if not p.relative_to(ROOT).as_posix().startswith(('planner/', 'briefing/')):
  s=s.replace('</head>', '<script src="/ads.js?v=oz9" async></script>\n</head>')
 s=s.replace('FIELD KNOWLEDGE / V1.0','CIVILIAN KNOWLEDGE / FREE ACCESS')
 s=s.replace('When an emergency is active, follow local official instructions.','Act on danger. Verify information. Plan for help to be unavailable.')
 s=re.sub(r'/(styles.css|app.js|search.js)\?v=oz\d+',lambda m:'/'+m[1]+'?v=oz7',s)
 if '<footer' in s and 'href="/topics/"' not in s[s.index('<footer'):]:
  s=s.replace('<a href="/resources/">Reference shelf</a>','<a href="/topics/">All topics A–Z</a><a href="/resources/">Reference shelf</a>')
 if '<footer' in s and 'https://www.tiktok.com/@osprey_zero' not in s[s.index('<footer'):]:
  social='<div><b>FOLLOW</b><a href="https://www.tiktok.com/@osprey_zero" target="_blank" rel="noopener noreferrer">TikTok</a><a href="https://www.instagram.com/ospreyzero/" target="_blank" rel="noopener noreferrer">Instagram</a><a href="https://www.youtube.com/@OspreyZero" target="_blank" rel="noopener noreferrer">YouTube</a></div>'
  s=s.replace('</a></div></div></div><div class="wrap footer-bottom">','</a></div>'+social+'</div></div><div class="wrap footer-bottom">')
 if p==ROOT/'index.html':
  s=re.sub(r'<form class="library-search hero-search".*?</form>','',s,flags=re.S)
  s=s.replace('Practical knowledge for emergencies, everyday disruptions, and the places beyond the pavement. Find what matters, understand it quickly, and keep learning.','Practical steps for individuals and families when power, water, communications or outside help fail. Find the quick answer, make a workable plan and keep the essentials offline.')
  s=s.replace('Current local alerts and emergency instructions always take priority.','Built for people who may have to manage without outside help.')
  s=s.replace('Contact local emergency services. Follow current instructions from local authorities.','Take the first protective step now. Seek qualified help when reachable and safe; do not wait for a response to get out of danger.')
  s=s.replace('Find official sources','Find trusted references')
  s=s.replace('Choose a situation. Open an answer-first Osprey Zero guide. Current instructions for your location always come first.','Search what is happening, or choose a common situation. Every guide leads with the immediate action and includes a plan for when help is unavailable.')
  s=s.replace('Search power, storm, water, evacuation…','Search all topics: power, water, shelter…')
  s=s.replace('Save a checklist, open official guidance, then read the steps and exceptions.','Save the checklist, follow practical steps and read the limits. Independent and official references are there when you need deeper context.')
  s=s.replace('Check local alerts and urgent medical needs. Use battery light, keep the fridge closed, and run generators only outdoors away from openings.','Prioritise urgent medical power, safe temperature and drinking water. Use battery light, keep the fridge closed and keep generators outdoors at least 20 feet from openings.')
  s=s.replace('The 72-hour blackout field guide is in development. Join the early list and we’ll email you when it is ready. Short, practical, and designed to be useful when you have little time to spare.','The online blackout guides and checklists are free now. Join the early list for the upcoming extended printable field guide; access to emergency information never requires signup.')
  s=s.replace('Government guidance, public health references, and published field manuals have a separate source library for deeper reading and current instructions.','Independent humanitarian guidance, public health references and published field manuals provide deeper context. The practical action plan lives here and does not assume official help will arrive.')
  marker='    <section class="guide-method"'
  paths='''<section class="wrap mission-paths" aria-label="Common needs"><div><p class="kicker">WHEN SYSTEMS FAIL</p><h2>Find a workable plan.</h2></div><a href="/library/conflict/">Conflict & civilian safety</a><a href="/emergencies/long-blackout/">Days without power</a><a href="/library/evacuation-shelter/">Leaving home & staying together</a><a href="/library/utilities/">Water & sanitation</a><a href="/topics/">Every topic A–Z</a></section>'''
  s=re.sub(r'<section class="wrap mission-paths".*?</section>','',s,flags=re.S)
  s=s.replace(marker,paths+'\n'+marker)
 if '<footer' in s and 'href="/reading-list/"' not in s[s.index('<footer'):]:
  s=s.replace('<a href="/privacy/">Privacy</a>','<a href="/reading-list/">My reading list</a><a href="/privacy/">Privacy</a>')
 if '<footer' in s and 'href="/briefing/"' not in s[s.index('<footer'):]:
  s=s.replace('<a href="/resources/">Reference shelf</a>', '<a href="/resources/">Reference shelf</a><a href="/briefing/">Current-events briefing</a>')
 if '<footer' in s and 'href="/contact/"' not in s[s.index('<footer'):]:
  s=s.replace('<a href="/privacy/">Privacy</a>','<a href="/privacy/">Privacy</a><a href="/contact/">Contact & corrections</a>')
 if not LIVE_TOPICS:
  for old in ['Four topic toolkit editions are complete, with checkout opening soon.','Four topic toolkits are complete, with checkout opening soon.','Topic toolkits are available through Payhip, with printable A4 and US Letter resources and Excel calculators.']:
   s=s.replace(old,'Our topic toolkits are being redesigned. Purchases are paused while we refine the contents and verify delivery.')
 if p==ROOT/'about/index.html':
  s=s.replace('Our aim is to help people find a clear next step and develop lasting capability.','Our mission is to help individuals and families make practical decisions when services fail, assistance is unavailable or authorities are unsafe to approach. Civilian safety, family continuity and self-reliance guide the library.')
  s=s.replace('Guides will carry sources, review dates, scope, and a clear place for current local instructions.','Guides carry linked sources, update dates and clear limits. We distinguish protective guidance from household planning and do not claim independent clinical or specialist certification.')
  s=s.replace('The field library is being developed now. Join the Field Notes list for guide releases and practical updates.','The encyclopedia is free to read without an account. Four topic toolkits are complete, with checkout opening soon. Join Field Notes to request updates; email signup never unlocks emergency information.')
  s=s.replace('The encyclopedia and its printable checklists are free to read without an account.','The encyclopedia is free to read without an account. Four topic toolkits are complete, with checkout opening soon.')
 if p==ROOT/'privacy/index.html':
  start=s.index('>',s.index('<main id="main"'))+1;end=s.index('</main>',start)
  s=s[:start]+'<section class="wrap library-heading"><p class="kicker">PRIVACY &amp; ADVERTISING</p><h1>Your information. Your choice.</h1><p>Updated 10 October 2026. The online emergency guides are free to read without an account.</p></section><section class="wrap interior-section"><div class="prose"><h2>Search stays in your browser</h2><p>Osprey Zero ranks a search index locally. With JavaScript and tab storage available, browse-page searches transfer through session storage and search-page queries remain in local browser history state. Refreshing the search page restores that tab’s query. Queries are not sent to an Osprey Zero search service. If JavaScript or tab storage is unavailable, browse forms use a URL query, which can appear in browser history and hosting logs. Incoming shared search links can also contain query text. Avoid entering personal details.</p><h2>Briefing location preferences</h2><p>The briefing can match a ZIP-area estimate against a bundled Census county lookup in your browser. The ZIP you enter and your selected broad region are stored only in local browser storage when available; they are not added to a URL or sent to a geocoder, source feed or Osprey Zero lookup service. You can clear the preference in the briefing. A shared device may expose it, and clearing site data removes it. The site does not request GPS access. Loading the page, shared snapshot and lookup file still creates ordinary hosting requests, which may include an IP address. ZIP areas are approximate, the lookup has gaps, and a matching county does not establish danger at your address.</p><h2>Your reading list</h2><p>Saved guide links are stored locally in this browser. We store only the selected guide paths, not a downloaded copy of the content. The list has no account or cloud sync and clearing site data removes it. A shared device may expose your saved links. Guides still require an internet connection.</p><h2>Email requests</h2><p>The optional toolkit-update and Field Notes forms collect an email address through Netlify. Email delivery is awaiting setup; submitting a request does not promise an immediate message. Never put an emergency report or personal safety information in a signup form. Use the unsubscribe method in any future email to stop messages.</p><h2>Preparation toolkits and payments</h2><p>The topic toolkits are being redesigned. Website purchases are paused; final contents, edition and pricing will be confirmed before sales reopen. Checkout and purchased-file delivery will take place through Payhip and its payment providers. Osprey Zero will not collect card details or host purchased documents in this public website.</p><p><a href="https://payhip.com/privacy" target="_blank" rel="noopener noreferrer">Payhip privacy information</a></p><h2>Household Planner records</h2><p>The separate Household Planner web launcher verifies and stores a purchased app file locally in this browser. Imported files and household records are not uploaded by the launcher. There is no account or cloud synchronization. Export editable backups regularly: browser storage eviction, clearing site data or removing an installed app can remove local copies. Use shared devices carefully. The planner launch and product pages do not initialise advertising zones.</p><h2>Ads and third-party services</h2><p>Browsing, preparedness and field-guide pages automatically load Monetag advertising to support the free encyclopedia. Ads may use cookies, browser storage, IP addresses and device information for delivery, measurement and fraud prevention. The vignette zone may display a dismissible advertising overlay. The separate push-subscription prompt has been disabled. Advertising is separate from our guidance and is not an endorsement.</p><p>The homepage, search, urgent response pages, toolkit pages, privacy page, contact page and signup confirmation do not initialise ad zones. Eligible browsing and reading pages continue to load the vignette zone. The site no longer initialises the separate push-notification subscription tag. Disaster-scam and information-verification articles are eligible reading pages; other emergency articles stay ad-free. There is no paid ad-free plan or site control to disable ads. Provider and browser settings control ad appearance and frequency.</p><p>Previously granted notification permissions are not automatically revoked. Existing advertising notifications may continue until you revoke permission through your browser\'s site settings. The supplied root advertising service worker remains in place for existing subscriptions; it does not provide emergency alerts.</p><p><a href="https://monetag.com/privacy/" target="_blank" rel="noopener noreferrer">Monetag privacy information</a> · <a href="https://www.netlify.com/privacy/" target="_blank" rel="noopener noreferrer">Netlify privacy information</a></p><h2>Browser storage and retired offline access</h2><p>The former offline reader and free document downloads have retired. When you return to the site, it attempts to remove only the former Osprey Zero offline cache and its worker. Browser restrictions or a device that never reconnects can prevent cleanup. Previously downloaded files remain on your device until you delete them. Fonts are hosted locally. Hosting and advertising services may retain request logs or use their own storage.</p><h2>Corrections and privacy requests</h2><p><a href="https://github.com/LaChance971123/briksurvival-site/issues/new" target="_blank" rel="noopener noreferrer">Report an editorial correction</a>. This is a public issue form: do not include names, locations, email addresses or other sensitive details. For a private correction, product question or privacy request, use our <a href="/contact/">contact form</a>. Netlify stores the submitted name, email, topic and message for the site operator to review. This is not an emergency service; response times are not guaranteed. Do not send medical records, live locations, passwords or payment card details.</p><h2>Safer browsing in a crisis</h2><p>Do not share live family locations or sensitive identity information through public links. Household worksheets in future products are intended to be completed on your own device and kept privately.</p></div></section>'+s[end:]
 if p==ROOT/'thanks/index.html':
  start=s.index('>',s.index('<main id="main"'))+1;end=s.index('</main>',start)
